import sys; sys.path.insert(0,'/home/claude/ac-mdcu/parts')
from l23_common import mk, save
Q={}

mk(Q, 101, [64, 's25', 's26'],
 stem='''Five adults attend a burn clinic. Which one has an indication for early excision and grafting?''',
 opts=['''A man with a red, dry, blanching sunburn over 10% TBSA''','''A woman with a mature, stable scar from a burn that healed two years ago''','''A woman with 4% TBSA blistered, moist, pink burns of the forearm''','''A man with a 6% TBSA leathery, insensate burn with sharp margins''','''A man with blistered fingertips from a hot cup that blanch briskly'''],
 interp='''ผู้ใหญ่ 5 รายมีแผลไหม้คนละแบบ → ต้องแยกความลึกจากลักษณะแผล (แดงแห้ง = superficial · ตุ่มน้ำ ชื้น ชมพู กดซีด = superficial partial · แข็งเหมือนหนัง ไม่รู้สึก = full thickness) → ถามว่ารายใดเข้าข้อบ่งชี้ early excision and grafting ต้องใช้เกณฑ์แรก: full thickness แน่นอน ขอบเขตชัด ไม่เกิน 10% TBSA''',
 why='''Early excision and grafting คือการ<b>ตัดเนื้อตายออกตั้งแต่ช่วงวันแรก ๆ</b> (ส่วนใหญ่ภายในสัปดาห์แรกเมื่อ resuscitation คงที่) แล้ว<b>ปิดด้วย skin graft ทันที</b> แทนการรอให้ eschar แยกตัวเอง — แผล <b>full thickness</b> ไม่มี dermal appendage เหลือให้ผิวงอกจากพื้นแผล ถ้าปล่อยจะหายช้าด้วยการหดรั้งจากขอบและเกิดแผลเป็นมาก ทั้งเนื้อตายยังเป็นแหล่งเชื้อและสารอักเสบ · ข้อบ่งชี้มี 3 กลุ่ม: (1) <b>full thickness แน่นอน ขอบเขตชัด ไม่เกิน 10% TBSA</b> พบบ่อยใน contact burn — ตัดออกได้หมดในครั้งเดียวโดยเสียเลือดไม่มาก (2) <b>deep partial ค่อนข้างกว้าง</b>ที่อาจมี full thickness ปน (3) <b>แผลลึกกว้างคุกคามชีวิต</b> · แผลแข็งเหมือนหนัง ไม่รู้สึก ขอบคม 6% จึงเข้ากลุ่มแรกพอดี ส่วนแผลแดงแห้งหรือตุ่มน้ำชื้นที่กดซีดกลับเร็วยังมี dermis และ appendage หายเองใน 1–2 สัปดาห์ การตัดออกมีแต่ทำลายผิวที่หายได้ · สไลด์หน้า 64 <b>"1.Undoubted full thickness burns with clearly defined edges up to 10 percent surface area."</b>''',
 wrong={
 'A':'''ผิวแดง แห้ง กดซีด ไม่มีตุ่มน้ำ = superficial (first-degree) burn ทำลายเฉพาะ epidermis หายเองใน 3–7 วันโดยไม่มีแผลเป็น และไม่นับรวมใน %TBSA เวลาคำนวณน้ำ ขนาด 10% จึงไม่มีความหมายต่อการผ่าตัด · ไม่มีสถานการณ์ใดที่แผล superficial burn ต้องตัดเนื้อตายและปลูกผิว เพราะไม่มีเนื้อตายให้ตัด ชั้น basal ยังอยู่ครบ การรักษาคือยาแก้ปวด ครีมให้ความชุ่มชื้น และกันแดด''',
 'B':'''แผลเป็นที่หายและนิ่งแล้วไม่มีเนื้อตายให้ตัด คำว่า early หมายถึงการตัดเนื้อตายของแผลไหม้สดในช่วงวันแรก ๆ ก่อนแผลจะหายเองหรือติดเชื้อ · ไม่มีสถานการณ์ใดที่แผลเป็นอายุ 2 ปีเป็นข้อบ่งชี้ early excision เพราะปัญหาของแผลเป็นระยะนี้ เช่น ดึงรั้งข้อหรือแตกซ้ำ แก้ด้วยการผ่าตัดแก้แผลเป็น (scar release ร่วมกับ graft หรือ flap) ซึ่งเป็นการผ่าตัดระยะ reconstruction คนละขั้นตอน''',
 'C':'''ตุ่มน้ำ ชื้น ชมพู = superficial partial thickness ยังมี dermis ส่วนลึกและ appendage จำนวนมาก ผิวงอกจากรูขุมขนและต่อมได้ หายใน 10–14 วันโดยแทบไม่มีแผลเป็นถ้าป้องกันการติดเชื้อ · ไม่มีสถานการณ์ใดที่แผล superficial partial thickness 4% ต้องตัดเนื้อตาย เพราะการตัดจะทำลายแหล่งเซลล์ที่ทำให้แผลหายเอง การรักษาคือ conservative ทำแผลด้วยยาทาหรือ dressing จนหาย''',
 'E':'''นิ้วมีตุ่มน้ำและกดซีดแล้วสีกลับเร็ว แสดงว่าเส้นเลือดใน dermis ยังดี = superficial partial thickness จากของเหลวร้อนสัมผัสสั้น ๆ แม้มือเป็นตำแหน่งสำคัญที่ควรส่งต่อ burn center แต่ความลึกระดับนี้หายเอง · ไม่มีสถานการณ์ใดที่ตุ่มน้ำปลายนิ้วซึ่งกดซีดกลับเร็วต้องตัดเนื้อตาย เพราะยังมี dermis และ appendage พอให้ผิวงอก สิ่งที่ต้องทำคือทำแผล ยกมือสูงลดบวม และให้ขยับนิ้วเร็ว'''},
 trap='''คิดว่าขนาดแผลเป็นตัวตัดสินจึงเลือกรายที่ 10% หรือคิดว่าแผลที่มือต้องผ่าตัดเสมอ — เกณฑ์ early excision ดูความลึกก่อนขนาด: แผลที่ยังมีตุ่มน้ำ ชื้น กดซีดหายเองได้ ส่วนแผลแข็งเหมือนหนัง ไม่รู้สึก ขอบชัด คือ full thickness ที่ต้องตัดและปลูกผิว''',
 summary=['''Full thickness แน่นอน + ขอบเขตชัด + ไม่เกิน 10% TBSA = ข้อบ่งชี้แรกของ early excision and grafting''',
  '''อีก 2 ข้อบ่งชี้: deep partial ค่อนข้างกว้างที่มี full thickness ปน · แผลลึกกว้างที่คุกคามชีวิต''',
  '''ลักษณะ full thickness: ขาวหรือน้ำตาล แข็งเหมือนหนัง ไม่เจ็บ ไม่กดซีด อาจเห็นเส้นเลือดใต้ผิวอุดตันเป็นลายกิ่งไม้''',
  '''กลุ่มแรกพบบ่อยใน contact burn จากวัตถุร้อนจัด เป้าหมาย: ตัดเนื้อตายทั้งหมดให้เร็วที่สุดแล้วปิดด้วย graft (ชีทหน้า 26)''',
  '''วิธีตัด 2 แบบ: ตัดออกทั้งหมด (scalpel excision) หรือเฉือนทีละชั้น (tangential excision) จนถึงเนื้อที่มีเลือดออกเป็นจุด''',
  '''แผลตื้น (superficial, superficial partial) หายเองใน 1–2 สัปดาห์ — ไม่ตัด'''],
 opinion='''เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ตรงกับข้อบ่งชี้แรกในสไลด์หน้า 64 และชีทหน้า 25 ทั้งความลึก ขอบเขต และขนาด · แนวทางปัจจุบัน (ISBI Practice Guidelines 2016) ใช้หลักว่าแผลที่คาดว่าจะไม่หายเองภายในราว 3 สัปดาห์ควรตัดและปลูกผิวแต่เนิ่น ๆ โดยไม่ได้กำหนดเพดาน 10% — ตัวเลข 10% ในชีทหน้า 26 สะท้อนความปลอดภัยเรื่องการเสียเลือดต่อการผ่าตัดหนึ่งครั้งเมื่อผู้ผ่าตัดยังไม่คุ้นเคย มากกว่าจะเป็นข้อห้ามของแผลที่ใหญ่กว่า''',
 mnemonic='''<b>"ลึกจริง ขอบชัด ไม่เกินสิบ → ตัดเลย"</b>''',
 guide='''ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon's Total Burn Care 5th ed. (2018) — Operative wound management''',
 variants=['''หญิงแผล full thickness ขอบชัด 4% ที่ด้านหน้าคอ หลังตัดเนื้อตาย → ปิดด้วย sheet graft ไม่ mesh เพื่อลดการหดรั้งและได้รูปลักษณ์ที่ดีกว่า''',
  '''ชายแผล full thickness ขอบชัด 7% ที่หน้าแข้ง ตัดเนื้อตายแล้วเห็นเอ็นและกระดูกที่ไม่มี paratenon หรือ periosteum คลุม → skin graft ไม่ติดบนพื้นที่ไม่มีเลือดเลี้ยง ต้องปิดด้วย flap''',
  '''ชายได้ split-thickness graft หลังตัดแผล full thickness 6% เปิดแผลวันที่ 4 พบเลือดคั่งใต้แผ่นผิว → graft ไม่ติดเพราะ hematoma กั้นการซึมของพลาสมา ต้องระบายออก ป้องกันด้วยห้ามเลือดให้ดีและกดยึดแผ่นผิว'''])

mk(Q, 102, [64, 's25', 's26'],
 stem='''A 30-year-old man has 60% TBSA burns, mostly deep partial and full thickness, without inhalation injury. By 48 hours his resuscitation is complete and he is hemodynamically stable. What is the role of early excision and grafting?''',
 opts=['''Exposure treatment of all wounds should be used instead''','''It should be deferred until the eschar separates spontaneously''','''It is reserved for the face and the hands''','''It is contraindicated once a burn exceeds 50% TBSA''','''It is indicated, usually as staged excisions'''],
 interp='''ชายแผลลึก (deep partial + full thickness) 60% ไม่มี inhalation injury ผ่านช่วง resuscitation แล้ว hemodynamics คงที่ → แผลกว้างลึกที่คุกคามชีวิต → ถามบทบาทของ early excision ในแผลกว้างมาก ต้องใช้ข้อบ่งชี้ที่สามและหลักการตัดเป็นรอบตามที่ผู้ป่วยทนได้''',
 why='''แผลลึกกว้าง 60% คือข้อบ่งชี้ที่สามของ early excision — <b>extensive life-threatening burns</b> ที่ลึกระดับ deep partial และ full thickness · เหตุผล: eschar ที่ค้างอยู่เป็น<b>แหล่งเชื้อ</b>ที่ยาทางหลอดเลือดเข้าไม่ถึง และเป็นต้นทางของ<b>สารอักเสบและ hypermetabolism</b> แผลเปิดยังเสียน้ำ โปรตีน และความร้อนต่อเนื่อง การตัดออกเร็วแล้วปิดแผลจึงลด burn wound sepsis ลดวันนอน และ RCT ของ Herndon (1989) กับ meta-analysis ปี 2006 พบลดอัตราตายในผู้ป่วยที่ไม่มี inhalation injury · ข้อจำกัดหลักคือ<b>เสียเลือดมาก</b> จึงทำแบบ <b>staged</b>: เริ่มเมื่อ resuscitation คงที่ (ราว 48–72 ชม.) ตัดเป็นรอบห่างกันไม่กี่วัน เริ่มจากบริเวณกว้างและลึกที่สุด หยุดเมื่อตัวเย็น เลือดออกมาก หรือเกิด coagulopathy ส่วนที่ autograft ไม่พอคลุมชั่วคราวด้วย allograft หรือผิวทดแทน แล้วเปลี่ยนเป็น autograft เมื่อ donor site หายพอเก็บซ้ำ · สไลด์หน้า 64 <b>"3.Extensive life-threatening burns with deep partial thickness and full thickness depth."</b>''',
 wrong={
 'A':'''Exposure treatment เป็นการรักษาแบบ conservative ปล่อยแผลให้แห้ง เย็น สัมผัสอากาศ ใช้กับแผลด้านเดียวของลำตัวหรือแขนขา หน้า และฝีเย็บ ไม่ได้เอาเนื้อตายออก แผลลึกกว้างจึงยังเป็นแหล่งเชื้อ · จะถูกถ้าชายมีแผล superficial partial thickness เฉพาะด้านหลังลำตัว ซึ่งหายเองได้ภายใน 2 สัปดาห์และไม่มีบทบาทของการตัดเนื้อตาย จึงใช้ exposure treatment แทนการผ่าตัด''',
 'B':'''การรอให้ eschar แยกตัวเองแล้วปลูกผิวบน granulation คือแนวทาง conservative เดิม ใช้เวลาหลายสัปดาห์ ระหว่างนั้นเสี่ยง burn wound sepsis เสียโปรตีน และแผลเป็นมาก ไม่เหมาะกับผู้ป่วยหนุ่มที่ทนการผ่าตัดได้ · จะถูกถ้าหญิงอายุ 92 ปีแผล full thickness 8% ที่ขา มีโรคหัวใจรุนแรงจนดมยาไม่ได้และครอบครัวเลือกไม่ผ่าตัด จึงทำแผลด้วยยาทาจน eschar หลุดเอง แล้วปลูกผิวเท่าที่ทำได้''',
 'C':'''หน้าและมือเป็นตำแหน่งสำคัญด้านการใช้งานและรูปลักษณ์ แต่ early excision ใช้กับแผลลึกทุกตำแหน่ง — ในแผลกว้างมักเริ่มจากลำตัวและแขนขาที่มีพื้นที่มากที่สุดก่อน ส่วนหน้าตัดอย่างระมัดระวังและบางครั้งรอให้ส่วนที่หายเองได้แสดงตัวก่อน · ไม่มีสถานการณ์ใดที่ early excision สงวนไว้เฉพาะหน้าและมือ เพราะข้อบ่งชี้ทั้ง 3 กลุ่มอิงความลึกและขนาดของแผล ไม่ได้อิงตำแหน่ง''',
 'D':'''ไม่มีเพดาน %TBSA ที่ห้ามตัด ยิ่งแผลลึกกว้างยิ่งได้ประโยชน์จากการเอาเนื้อตายออกเร็ว ข้อจำกัดคือการเสียเลือดซึ่งแก้ด้วยการตัดเป็นรอบ ไม่ใช่งดผ่าตัด · ไม่มีสถานการณ์ใดที่ขนาดแผลเกิน 50% เป็นข้อห้ามของ early excision ในตัวเอง เพราะแผลกว้างคุกคามชีวิตคือข้อบ่งชี้ที่สาม — สิ่งที่ทำให้เลื่อนผ่าตัดคือภาวะของผู้ป่วย เช่น ช็อกที่ยังไม่คงที่หรือ coagulopathy'''},
 trap='''เห็นแผล 60% แล้วกลัวเสียเลือดจนคิดว่าใหญ่เกินผ่าตัด หรือเอาตัวเลข 10% ของข้อบ่งชี้แรกมาใช้ปนกัน — เพดาน 10% เป็นของแผล full thickness ขอบชัดกลุ่มแรก ส่วนแผลกว้างคุกคามชีวิตเป็นข้อบ่งชี้แยก และแก้ปัญหาเลือดด้วยการตัดเป็นรอบ''',
 summary=['''แผลลึกกว้างคุกคามชีวิต (deep partial + full thickness) = ข้อบ่งชี้ที่สามของ early excision — ทำแบบ staged''',
  '''เริ่มเมื่อ resuscitation คงที่ราว 48–72 ชม. ไม่ผ่าตัดกลางช่วง burn shock''',
  '''ประโยชน์: เอาแหล่งเชื้อและสารอักเสบออก ลด hypermetabolism · ลดการเสียน้ำและโปรตีนจากแผลเปิด · ลดวันนอน''',
  '''ราคาที่ต้องจ่าย: เสียเลือดมาก ตัวเย็น coagulopathy → ตัดเป็นรอบห่างกันไม่กี่วัน เริ่มจากบริเวณกว้างที่สุด''',
  '''autograft ไม่พอ → mesh ขยาย หรือคลุมชั่วคราวด้วย allograft หรือผิวทดแทนจนกว่า donor site จะเก็บซ้ำได้''',
  '''ชีทหน้า 26 ระบุว่ากลุ่มที่สามอัตราตายไม่ต่างจาก conservative — งานที่ใหม่กว่าพบลดอัตราตายในรายที่ไม่มี inhalation injury'''],
 opinion='''เห็นด้วยกับคำตอบ E ความมั่นใจสูง — ตรงข้อบ่งชี้ที่สามในสไลด์หน้า 64 และชีทหน้า 26 · จุดต่าง: ชีทหน้า 26 เขียนว่าในกลุ่มนี้อัตราการเสียชีวิตไม่ต่างจาก conservative treatment แต่ RCT ของ Herndon (Ann Surg 1989) พบลดอัตราตายในผู้ใหญ่อายุน้อยที่ไม่มี inhalation injury และ meta-analysis ของ Ong (Burns 2006) พบลดอัตราตายและวันนอนแลกกับการใช้เลือดมากขึ้น ISBI Practice Guidelines 2016 จึงถือ early excision เป็นมาตรฐานของแผลลึกกว้าง''',
 mnemonic='''<b>"กว้าง ลึก ถึงชีวิต → ตัดเป็นรอบ ไม่รอหลุดเอง"</b>''',
 guide='''ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon DN et al. A comparison of conservative versus early excision therapies in severely burned patients (Ann Surg 1989;209:547–553); Ong YS et al. Meta-analysis of early excision of burns (Burns 2006;32:145–150)''',
 variants=['''ชายแผลลึก 60% ระหว่างตัดเนื้อตายรอบแรก อุณหภูมิกายลดเหลือ 34.5°C และเลือดเริ่มซึมทั่วพื้นแผล → หยุดตัด คลุมส่วนที่ตัดแล้ว แก้ตัวเย็นและ coagulopathy แล้วตัดต่อในรอบถัดไป''',
  '''หญิงแผล full thickness 75% เหลือผิวดีให้เก็บ donor น้อยมาก → ใช้ widely meshed autograft ร่วมกับผิวทดแทน หรือ cultured epidermal autograft เพื่อปิดแผลถาวรเป็นระยะ''',
  '''ชายแผลลึก 55% ที่ตัดเนื้อตายแล้วใช้ mesh graft อัตรา 3:1 คลุมลำตัว → ช่องตาข่ายหายจากผิวที่งอกจากขอบ แต่เหลือแผลเป็นลายตาข่ายถาวร จึงเลี่ยงใช้ mesh กว้างที่หน้าและมือ'''])

mk(Q, 103, [64, 's25', 's26'],
 stem='''A 27-year-old woman has a moderately extensive scald of the thigh. Most of it is deep partial thickness, with a few full-thickness patches. Which treatment is supported?''',
 opts=['''Dressings and observation for three months''','''Exposure treatment until spontaneous healing''','''A pressure garment applied over the open wound''','''Early excision and grafting''','''Escharotomy as the definitive procedure'''],
 interp='''แผลน้ำร้อนลวกที่ต้นขาขนาดค่อนข้างกว้าง ส่วนใหญ่ deep partial มี full thickness ปนบางหย่อม → ตรงข้อบ่งชี้ที่สองของ early excision → ถามการรักษาที่เหมาะสม ต้องรู้ว่า deep partial หายเองได้แต่ช้าและแผลเป็นมาก ส่วนหย่อม full thickness ไม่หายเองเลย''',
 why='''<b>Deep partial thickness</b> ทำลาย dermis ส่วนลึก เหลือ appendage น้อย ผิวงอกได้แต่<b>ช้า 3 สัปดาห์ขึ้นไป</b> และแผลที่ใช้เวลาหายเกินราว 21 วัน<b>เสี่ยงแผลเป็นนูน (hypertrophic scar) และหดรั้งสูงมาก</b> ส่วนหย่อม full thickness ไม่หายเองเลย · ข้อบ่งชี้ที่สองจึงเลือก <b>early excision and grafting</b>: ในปี 1970 <b>Janzekovic</b> เสนอ <b>tangential excision</b> คือเฉือน eschar ออกทีละชั้นบาง ๆ ด้วยมีด Watson หรือ dermatome จนถึง <b>dermis ที่มีเลือดออกเป็นจุด (punctate bleeding)</b> แล้วปิดด้วย split-thickness graft ทันที เพื่อเก็บ dermis ดีไว้มากที่สุดและให้แผลเป็นน้อย ข้อเสียคือรอยต่อ dermis–ไขมันไม่เรียบ อาจเฉือน dermis ดีทิ้งไปบ้าง และเลือดออกมาก · ผลคือแผลปิดเร็ว ลดวันนอนและการติดเชื้อ และคุณภาพแผลเป็นดีกว่าปล่อยหายเอง · ชีทหน้า 25 <b>"2.บาดแผลไฟไหม้น้ำร้อนลวกระดับที่สองลึก (deep partial thickness burns) ที่ค่อนข้างรุนแรง และอาจจะมีบางส่วนเป็นบาดแผลไฟไหม้น้ำร้อนลวกระดับที่สาม"</b>''',
 wrong={
 'A':'''การทำแผลและเฝ้าดูยาวนานปล่อยให้แผลลึกเปิดอยู่หลายเดือน ส่วน deep partial ที่หายเกิน 3 สัปดาห์มีแผลเป็นนูนสูง และหย่อม full thickness ไม่หายเองนอกจากหดรั้งจากขอบ ระหว่างนั้นเสี่ยงติดเชื้อตลอด · ไม่มีสถานการณ์ใดที่แผลไหม้ลึกควรปล่อยเปิดเฝ้าดูถึง 3 เดือน เพราะแผลที่ไม่หายใน 2–3 สัปดาห์ต้องปลูกผิว แม้แผลที่ความลึกไม่ชัดก็รอแยกความลึกเพียง 14–21 วัน''',
 'B':'''Exposure treatment ปล่อยแผลแห้ง เย็น สัมผัสอากาศ เหมาะกับแผลด้านเดียวของลำตัวหรือแขนขา หน้า และฝีเย็บ ไม่ได้เร่งการหายของแผลลึก และไม่แก้ปัญหาหย่อม full thickness · จะถูกถ้าชายมีแผลน้ำร้อนลวก superficial partial thickness เฉพาะด้านหลังลำตัวด้านเดียว ซึ่งหายเองใน 10–14 วัน จึงรักษาแบบ exposure ได้โดยไม่ต้องผ่าตัด''',
 'C':'''Pressure garment กดคุมแผลเป็นนูนให้แบนและสุกเร็วขึ้น แต่ใช้กับแผลที่ปิดสนิทแล้ว สวมบนแผลเปิดจะเสียดสีผิวที่งอกใหม่และทำให้แผลแย่ลง · ไม่มีสถานการณ์ใดที่สวม pressure garment บนแผลที่ยังเปิด เพราะผ้ารัดจะถูไถเยื่อบุผิวใหม่จนหลุด จึงเริ่มใส่เมื่อแผลหายหรือ graft ติดแน่นแล้ว และใช้คุมแผลเป็น ไม่ได้ใช้รักษาแผลสด''',
 'E':'''Escharotomy คือกรีดผ่า eschar ถึงชั้นไขมันเพื่อปลดการรัดของแผลลึกรอบวงที่บีบเส้นเลือดหรือขัดการขยายของทรวงอก ไม่ได้เอาเนื้อตายออกหรือปิดแผล · ไม่มีสถานการณ์ใดที่ escharotomy เป็นการรักษาแผลไหม้แบบ definitive เพราะหลังกรีดแล้วเนื้อตายยังอยู่ครบ ต้องตามด้วยการตัดเนื้อตายและปลูกผิวเสมอ escharotomy เป็นเพียงหัตถการกู้เลือดเลี้ยงอวัยวะในระยะแรก'''},
 trap='''Deep partial "หายเองได้" จึงคิดว่าทำแผลรอหรือใช้ exposure ก็พอ — แต่หายเองได้ไม่เท่ากับควรรอ: แผลที่ใช้เวลาเกิน 3 สัปดาห์เกิดแผลเป็นนูนและหดรั้งมาก บวกกับหย่อม full thickness ที่ไม่หายเอง จึงตรงข้อบ่งชี้ที่สอง''',
 summary=['''Deep partial ค่อนข้างกว้าง ± หย่อม full thickness = ข้อบ่งชี้ที่สองของ early excision and grafting''',
  '''Deep partial: ขาวซีด ยังนุ่ม ความรู้สึกลด หายเอง 3–4 สัปดาห์ ทิ้งแผลเป็นมาก''',
  '''หายเกินราว 21 วัน → เสี่ยง hypertrophic scar สูง เป็นเหตุผลหลักที่ตัดและปลูกผิวแต่เนิ่น ๆ''',
  '''Tangential excision (Janzekovic 1970): เฉือนทีละชั้นจนเห็น punctate bleeding ใน dermis แล้ว graft ทันที — เก็บ dermis ไว้ได้มากที่สุด''',
  '''ข้อด้อยของ tangential: เลือดออกมาก · รอยต่อ dermis–ไขมันไม่เรียบอาจเฉือน dermis ดีทิ้ง (ชีทหน้า 26)''',
  '''ไม่ใช่การรักษาแผลลึก: exposure · pressure garment บนแผลเปิด · escharotomy อย่างเดียว'''],
 opinion='''เห็นด้วยกับคำตอบ D ความมั่นใจสูง — ตรงข้อบ่งชี้ที่สองในสไลด์หน้า 64 และชีทหน้า 25 · แนวทางปัจจุบัน (ISBI Practice Guidelines 2016) ใช้หลักเดียวกันแต่เขียนเป็นเวลา: แผลที่ประเมินแล้วว่าจะไม่หายภายในราว 3 สัปดาห์ให้ตัดและปลูกผิว ไม่ต้องรอให้ eschar แยกตัว · ในแผลที่ความลึกไม่ชัด ชีทและสไลด์ให้รอ 14–21 วัน แต่ปัจจุบันประเมินความลึกซ้ำในวันที่ 3–5 (อาจใช้ laser Doppler imaging ช่วย) แล้วตัดสินใจผ่าตัดเร็วกว่านั้น''',
 mnemonic='''<b>"ลึกปนลึกสุด → เฉือนจนเลือดผุด แล้วแปะผิว"</b>''',
 guide='''ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Janzekovic Z. A new concept in the early excision and immediate grafting of burns (J Trauma 1970;10:1103–1108); Sabiston Textbook of Surgery 21st ed. (2022) — Burns''',
 variants=['''ระหว่าง tangential excision เฉือนแล้วยังเห็น dermis สีเทาที่มีจุดเลือดอุดตันและไม่มีเลือดซึม → ยังไม่ถึงชั้นดี ต้องเฉือนต่อจนเห็น punctate bleeding ก่อนวาง graft''',
  '''หญิงแผลลึกปนหลายระดับทั่วใบหน้า → หลายศูนย์รอราว 10 วันให้ส่วนที่จะหายเองแสดงตัวก่อน แล้วตัดเฉพาะส่วนที่เหลือโดยปลูกผิวตาม aesthetic unit''',
  '''ชายแผล full thickness ที่มี invasive fungal infection ลุกลามลงชั้นไขมัน → fascial excision ตัดถึง fascia เลือดออกน้อยและเอาเนื้อติดเชื้อออกหมด แลกกับรูปร่างบุ๋มถาวร'''])

mk(Q, 104, [66, 's30'],
 stem='''A 30-year-old man with 25% TBSA partial-thickness burns is treated with twice-daily 1% silver sulfadiazine. On day 3 he is afebrile, his wounds look clean, and his vital signs and urine output are normal. His white cell count has fallen from 9,000 to 2,800/µL, with normal hemoglobin and platelets. What is the most likely cause?''',
 opts=['''Transient leukopenia caused by the topical agent''','''Early burn wound sepsis consuming neutrophils''','''Hemodilution from resuscitation fluids''','''Aplastic anemia from sulfonamide exposure''','''Carbon monoxide poisoning from smoke inhaled at the scene'''],
 interp='''ผู้ป่วยแผล partial thickness 25% ทา SSD วันละ 2 ครั้ง วันที่ 3 WBC ลดจาก 9,000 เหลือ 2,800 เพียงสายเดียว ไม่มีไข้ แผลสะอาด สัญญาณชีพและปัสสาวะปกติ Hb และเกล็ดเลือดปกติ → ถามสาเหตุ ต้องรู้ผลข้างเคียงประจำตัวของ SSD และแยกจาก sepsis ที่มักมีความผิดปกติหลายระบบร่วม''',
 why='''<b>Silver sulfadiazine 1%</b> เป็นยาทาที่ใช้มากที่สุด ข้อเสียประจำตัวมี 2 ข้อคือ pseudoeschar และ <b>transient leukopenia</b> · ลักษณะของ leukopenia: เกิดใน<b>ราววันที่ 2–3</b>หลังเริ่มยา ลดเฉพาะ<b>เม็ดเลือดขาวสายเดียว</b> (Hb และเกล็ดเลือดปกติ) ระดับ<b>มักไม่ต่ำกว่า 2,000/mm³</b> และ<b>กลับปกติเองแม้ใช้ยาต่อ</b> เชื่อว่าเกิดจากเม็ดเลือดขาวไปเกาะผนังหลอดเลือดและค้างอยู่ในแผล (margination) มากกว่าไขกระดูกถูกกดจริง · ก่อนสรุปว่าเป็นผลของยาต้องแน่ใจว่า<b>ไม่มีสัญญาณ sepsis</b>: ไข้สูงหรือตัวเย็น หัวใจเร็ว หายใจเร็ว เกล็ดเลือดลด น้ำตาลสูง ลำไส้ไม่ทำงาน หรือแผลเปลี่ยนสี ซึ่งผู้ป่วยในโจทย์ไม่มีเลย · SSD ยังเป็น sulfonamide จึงต้องระวังในผู้แพ้ sulfa, G6PD deficiency, ทารกอายุต่ำกว่า 2 เดือน และหญิงตั้งครรภ์ใกล้คลอด · สไลด์หน้า 66 <b>"Disadvantages: Pseudoeschar · Leukopenia (WBC rarely&lt; 2000)"</b>''',
 wrong={
 'B':'''Burn wound sepsis ทำให้ WBC สูงหรือต่ำได้ แต่มักมาเป็นกลุ่มอาการหลายระบบ ไม่ใช่ WBC ลดสายเดียวในผู้ป่วยที่ดูดี ไม่มีไข้ แผลสะอาด · จะถูกถ้าชายแผลไหม้ 40% วันที่ 8 ที่ WBC ลดเหลือ 2,500 ร่วมกับไข้ 39.6°C หัวใจเร็ว หายใจเร็ว น้ำตาลสูงขึ้นทั้งที่ได้ insulin เท่าเดิม เกล็ดเลือดลด และแผลเปลี่ยนเป็นปื้นคล้ำ''',
 'C':'''ภาวะเลือดเจือจางจากน้ำปริมาณมากทำให้ค่าทุกสายลดลงพร้อมกันในสัดส่วนใกล้กัน ทั้ง Hb เกล็ดเลือด และ albumin ไม่ใช่ WBC ลดลงกว่าสามเท่าขณะที่ Hb ปกติ · จะถูกถ้าหญิงแผลไหม้ 45% วันที่ 2–3 หลังได้ crystalloid ปริมาณมาก แล้ว Hb เกล็ดเลือด WBC และ albumin ลดลงพร้อมกันราว 20–30% เมื่อน้ำจากนอกหลอดเลือดเริ่มกลับเข้าสู่กระแสเลือด''',
 'D':'''Aplastic anemia จาก sulfonamide พบน้อยมาก เป็นการกดไขกระดูกทุกสายและไม่ฟื้นเองในไม่กี่วัน ต่างจาก WBC ลดสายเดียวที่ Hb และเกล็ดเลือดปกติ · จะถูกถ้าหญิงที่กิน trimethoprim-sulfamethoxazole ต่อเนื่องหลายสัปดาห์ แล้วมีซีด เลือดออกง่าย ติดเชื้อซ้ำ ผลเลือดต่ำทั้งสามสาย และไขกระดูกมีเซลล์น้อย (hypocellular marrow)''',
 'E':'''พิษ CO ทำให้เนื้อเยื่อขาด O2 จากการแย่งจับ Hb และกด cytochrome oxidase อาจพบเม็ดเลือดขาวสูงจากภาวะเครียด แต่ไม่กดไขกระดูก และผู้ป่วยไม่มีอาการทางสมองหรือประวัติไฟไหม้ในที่ปิด · ไม่มีสถานการณ์ใดที่พิษ CO เป็นสาเหตุของ WBC ลดลงในวันที่ 3 เพราะ CO ถูกขับออกภายในไม่กี่ชั่วโมงเมื่อได้ O2 และกลไกของมันไม่ได้ทำลายเม็ดเลือดขาว'''},
 trap='''WBC ต่ำในผู้ป่วยไฟไหม้ทำให้นึกถึง sepsis ทันที — ให้ดูบริบท: เกิดวันที่ 2–3 หลังเริ่ม SSD ลดสายเดียว ไม่ต่ำกว่า 2,000 และไม่มีสัญญาณ sepsis อื่น = ผลของยา · ถ้ามีไข้หรือตัวเย็น เกล็ดเลือดลด ลำไส้ไม่ทำงาน หรือแผลเปลี่ยน ต้องคิดถึง sepsis ก่อน''',
 summary=['''WBC ลดสายเดียววันที่ 2–3 หลังเริ่ม SSD โดยไม่มีสัญญาณติดเชื้อ = transient leukopenia จากยา''',
  '''ลักษณะเด่น: ลดสายเดียว · มักไม่ต่ำกว่า 2,000/mm³ · กลับปกติเองโดยไม่ต้องหยุดยา (ชีทหน้า 30)''',
  '''กลไกที่เชื่อกันมากที่สุด: เม็ดเลือดขาวไปเกาะผนังหลอดเลือดและค้างในแผล (margination) ไม่ใช่ไขกระดูกถูกทำลาย''',
  '''แยกจาก burn sepsis: ไข้หรือตัวเย็น · หัวใจเร็ว หายใจเร็ว · เกล็ดเลือดลด · น้ำตาลสูง · ลำไส้ไม่ทำงาน · แผลเปลี่ยน''',
  '''ข้อดี SSD: broad spectrum รวม Candida · ปวดน้อย · ไม่เปื้อน · ซึมปานกลาง · ดูดซึมน้อย · ทาทุก 12–24 ชม.''',
  '''ระวัง SSD: แพ้ sulfa · G6PD deficiency · ทารกอายุต่ำกว่า 2 เดือน · ตั้งครรภ์ใกล้คลอด'''],
 opinion='''เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงสไลด์หน้า 66 และชีทหน้า 30 ทั้งช่วงเวลา ระดับ WBC และการไม่มีสัญญาณติดเชื้อ · ข้อควรรู้เพิ่ม: เกณฑ์ sepsis ในผู้ป่วยไฟไหม้ใช้ ABA Consensus 2007 ซึ่งต่างจาก SIRS ทั่วไป เพราะผู้ป่วยไฟไหม้มีไข้ต่ำ ๆ และหัวใจเร็วจาก hypermetabolism อยู่แล้ว · Cochrane review (Wasiak 2013) พบว่า SSD สัมพันธ์กับการหายช้ากว่า dressing ชนิดอื่นในแผล partial thickness หลายศูนย์จึงใช้ silver dressing กับแผลตื้นแทน''',
 mnemonic='''<b>"SSD วันที่ 3 WBC ร่วงแต่ไม่ต่ำกว่า 2,000 — ยาทำ ไม่ใช่เชื้อ"</b>''',
 guide='''Greenhalgh DG et al. American Burn Association consensus conference to define sepsis and infection in burns (J Burn Care Res 2007;28:776–790); Wasiak J et al. Dressings for superficial and partial thickness burns (Cochrane Database Syst Rev 2013); Herndon's Total Burn Care 5th ed. (2018) — Burn wound care''',
 variants=['''ทารกอายุ 3 สัปดาห์ถูกน้ำร้อนลวก 8% → เลี่ยง SSD เพราะ sulfonamide แย่งที่จับ albumin ของ bilirubin เสี่ยง kernicterus ใช้ยาทาหรือ dressing ที่ไม่มี sulfa''',
  '''ชายที่มี G6PD deficiency ทา SSD บนแผลกว้าง แล้วซีดลงเร็ว ปัสสาวะสีโค้ก indirect bilirubin สูง → hemolysis จาก sulfonamide ต้องหยุดยาและเปลี่ยนเป็นยาทาที่ไม่มี sulfa''',
  '''ชายแผลไหม้ 40% เจาะเลือดวันแรกพบ WBC 21,000 ไม่มีอาการติดเชื้อ → เม็ดเลือดขาวสูงจากภาวะเครียดหลังบาดเจ็บเป็นเรื่องพบบ่อย ไม่ใช่หลักฐานการติดเชื้อและไม่ใช่ข้อบ่งชี้ให้ยาปฏิชีวนะ'''])

mk(Q, 105, [65, 66, 67, 's29', 's30'],
 stem='''A 25-year-old woman has partial-thickness burns of the hand. Her team wants a topical agent that is broad-spectrum, nearly painless and does not stain. Which agent fits best?''',
 opts=['''1% silver sulfadiazine cream''','''Gentian violet paint''','''Povidone-iodine in an alcohol base''','''Mafenide acetate cream''','''0.5% silver nitrate soaks'''],
 interp='''แผล partial thickness ที่มือ ต้องการยาทาที่ครอบคลุมเชื้อกว้าง ปวดน้อย และไม่เปื้อนสี → ถามว่ายาทาตัวใดมีครบทั้งสามคุณสมบัติ ต้องจำข้อดีข้อเสียของยาทามาตรฐานสามตัว: SSD, mafenide และ silver nitrate แล้วตัดทีละเงื่อนไข''',
 why='''ยาทามาตรฐานสามตัวมีจุดเด่นต่างกัน: <b>SSD 1%</b> — broad spectrum ครอบคลุมแกรมบวก แกรมลบ รวมทั้ง <b>Candida</b> · <b>ปวดน้อย</b> · <b>ไม่เปื้อนสี</b> ล้างออกง่ายเพราะเป็นครีมฐานน้ำ · ซึมปานกลาง · ดูดซึมเข้าร่างกายน้อย · ทาทุก 12–24 ชม. จึงครบทั้งสามเงื่อนไข · <b>Mafenide</b> ซึมผ่าน eschar ดีที่สุดแต่<b>ปวดมาก</b> และทำให้ hyperchloremic metabolic acidosis · <b>Silver nitrate 0.5%</b> ไม่ปวดแต่<b>เปื้อนน้ำตาลดำ</b> ดึงเกลือแร่ออกทางแผล และต้องชุบให้เปียกทุก 2 ชม. · ส่วน gentian violet และ povidone-iodine ในแอลกอฮอล์ไม่ใช่ยาทาแผลไหม้มาตรฐาน · สำหรับแผลที่มือยังต้องให้ผ้าปิดบางพอขยับนิ้วได้ ยกมือสูงลดบวม และเริ่มกายภาพเร็ว · สไลด์หน้า 66 <b>"Advantages: Broad Spectrum · Minimal Pain · Nonstaining · Penetration-Intermediate · Rare Systemic Absorption · Applied q 12-24 hrs."</b>''',
 wrong={
 'B':'''Gentian violet เป็นสีย้อมฆ่าเชื้อที่เคยใช้ทาแผลตื้นและเชื้อรา ย้อมผิวและผ้าเป็นสีม่วงเข้ม ทำให้ประเมินแผลยาก และไม่ใช่ยาทาแผลไหม้มาตรฐาน · ไม่มีสถานการณ์ใดที่ gentian violet ตรงเงื่อนไขไม่เปื้อนสี เพราะคุณสมบัติพื้นฐานของมันคือสีย้อม และสีจะติดผิวอยู่หลายวันหลังหยุดทา''',
 'C':'''Povidone-iodine ในฐานแอลกอฮอล์ใช้ทำความสะอาดผิวก่อนผ่าตัด บนแผลไหม้เปิดจะแสบมาก เปื้อนสีน้ำตาล เป็นพิษต่อเซลล์ที่กำลังงอก และในแผลกว้างดูดซึมไอโอดีนจนรบกวนไทรอยด์และไตได้ · ไม่มีสถานการณ์ใดที่ povidone-iodine ในแอลกอฮอล์ตรงเงื่อนไขปวดน้อยและไม่เปื้อน เพราะแอลกอฮอล์ทำให้แผลเปิดแสบทุกครั้ง และไอโอดีนติดสีโดยธรรมชาติ''',
 'D':'''Mafenide ครอบคลุมเชื้อกว้างและซึมผ่าน eschar กับกระดูกอ่อนได้ดีที่สุด แต่ข้อเสียเด่นคือปวดแสบมากหลังทา และยับยั้ง carbonic anhydrase จนเกิด hyperchloremic metabolic acidosis เมื่อทาพื้นที่กว้าง · ไม่มีสถานการณ์ใดที่ mafenide ตรงเงื่อนไขปวดน้อย เพราะ Significantly Painful เป็นคุณสมบัติประจำตัวของยา จึงถูกเลือกเมื่อต้องการการซึมลึก ไม่ใช่เมื่อต้องการความสบาย''',
 'E':'''Silver nitrate 0.5% ครอบคลุมเชื้อกว้าง ไม่ปวดเวลาใช้ และดูดซึมน้อย แต่เมื่อสัมผัสผิว ผ้า และสิ่งของจะเป็นสีน้ำตาลหรือดำที่ล้างออกยาก ร่วมกับดึงเกลือแร่ออกทางแผล · ไม่มีสถานการณ์ใดที่ silver nitrate ตรงเงื่อนไขไม่เปื้อนสี เพราะรอยดำเกิดจากเงินที่ตกตะกอนเมื่อโดนแสงและสารอินทรีย์ ยานี้จึงเป็นทางเลือกเมื่อผู้ป่วยแพ้ sulfa และยอมรับรอยเปื้อนได้'''},
 trap='''SSD, mafenide และ silver nitrate เป็น broad spectrum เหมือนกัน คุณสมบัติแรกจึงแยกไม่ได้ — ต้องใช้อีกสองเงื่อนไขตัดทีละตัว: ปวดมาก = mafenide · เปื้อนดำ = silver nitrate · เหลือ SSD ที่ปวดน้อยและไม่เปื้อน''',
 summary=['''Broad spectrum + ปวดน้อย + ไม่เปื้อน = SSD 1% ยาทาที่ใช้แพร่หลายที่สุด''',
  '''SSD: ครอบคลุม Candida ด้วย · ซึมปานกลาง · ดูดซึมน้อย · ทาทุก 12–24 ชม. · ข้อเสีย pseudoeschar, leukopenia''',
  '''Mafenide: ซึม eschar ดีที่สุด + ซึมกระดูกอ่อน · ทาทุก 12 ชม. · ข้อเสีย ปวดมาก, carbonic anhydrase inhibitor → acidosis''',
  '''Silver nitrate 0.5%: กว้าง ไม่ปวด ดูดซึมน้อย · ข้อเสีย hypotonic ดึงเกลือแร่ · methemoglobinemia · เปื้อนดำ · ชุบทุก 2 ชม.''',
  '''จำแบบตัดออก: ปวด = mafenide · ดำ = silver nitrate · ที่เหลือ = SSD''',
  '''แผลที่มือ: dressing บางพอขยับนิ้ว · ยกสูง · กายภาพเร็ว'''],
 opinion='''เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงข้อดีครบทุกข้อในสไลด์หน้า 66 และชีทหน้า 29–30 · ข้อสังเกต: ในแผล partial thickness ปัจจุบันหลายศูนย์ใช้ dressing ที่มีเงิน (nanocrystalline silver, silver hydrofiber) หรือ biosynthetic dressing แทนการทา SSD วันละ 1–2 ครั้ง เพราะเปลี่ยนแผลน้อยครั้งกว่า และ Cochrane review (Wasiak 2013) พบ SSD สัมพันธ์กับการหายช้ากว่า — ส่วน ISBI Practice Guidelines 2016 ยังถือ SSD เป็นยาทาที่ใช้ได้โดยเฉพาะกับแผลลึก''',
 mnemonic='''<b>"ปวด = Mafenide · ดำ = Nitrate · สบายสะอาด = SSD"</b>''',
 guide='''ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Herndon's Total Burn Care 5th ed. (2018) — Burn wound care; Sabiston Textbook of Surgery 21st ed. (2022) — Burns''',
 variants=['''ชายแผลไหม้ partial thickness ที่ใบหน้า → มักใช้ขี้ผึ้ง bacitracin ทาบาง ๆ แบบเปิด เพราะครีม SSD หนา เลอะ และเสี่ยงเข้าตา''',
  '''หญิงแผลไหม้ลึก 30% ใช้ SSD แล้ว eschar หนาเริ่มนุ่มเละ มีหนองสีเขียวกลิ่นหวานใต้ eschar → เปลี่ยนเป็น mafenide ที่ซึมลงใต้ eschar และครอบคลุม Pseudomonas ได้ดีกว่า ร่วมกับตัดเนื้อตาย''',
  '''ชายแพ้ยา sulfa รุนแรงมีแผลไหม้ partial thickness 20% → เลี่ยงทั้ง SSD และ mafenide ใช้ silver nitrate 0.5% หรือ dressing ที่มีเงินแทน'''])

mk(Q, 106, [66, 's30'],
 stem='''Three days into silver sulfadiazine, a man's burns are covered by a yellow-gray film obscuring their depth. What is it?''',
 opts=['''Black deposits from silver precipitation''','''True full-thickness eschar''','''Invasive fungal wound infection''','''A vascularized, adherent skin graft''','''Pseudoeschar'''],
 interp='''ทา SSD มา 3 วัน แผลมีฟิล์มสีเหลืองเทาเกาะคลุมจนดูความลึกไม่ได้ → ถามว่าฟิล์มนี้คืออะไร ต้องรู้ข้อเสียของ SSD ที่เกิดหลังใช้ยา 2–3 วัน และแยกจาก eschar จริง การติดเชื้อรา และรอยเปื้อนของยาเงินชนิดอื่น''',
 why='''<b>Pseudoeschar</b> คือชั้นฟิล์มสีเหลืองเทาที่เกิดจาก<b>ครีม SSD จับกับสิ่งคัดหลั่ง (exudate) และโปรตีนจากแผล</b> แล้วจับตัวคลุมผิวแผล เกิดหลังใช้ยา<b>ราว 2–3 วัน</b> ดูคล้าย eschar จน<b>แยกจากเนื้อตายจริงได้ยาก</b> ทำให้ประเมินความลึกผิด และอาจทำให้เข้าใจผิดว่าแผลติดเชื้อหรือลึกกว่าความจริง · ต่างจาก eschar จริงตรงที่ pseudoeschar <b>เป็นชั้นผิวบนที่ล้างหรือเช็ดออกได้</b>ด้วยการทำความสะอาดอย่างนุ่มนวล และใต้ฟิล์มยังเห็นพื้นแผลชมพูชื้นของแผล partial thickness เดิม ส่วน eschar เป็นเนื้อตายที่ติดแน่นกับพื้นแผลตั้งแต่บาดเจ็บ · ป้องกันโดย<b>ล้างครีมเก่าออกให้หมดทุกครั้งก่อนทาใหม่</b> และทาเป็นชั้นบางสม่ำเสมอ · ข้อเสียอีกข้อของ SSD คือ leukopenia ชั่วคราว · ชีทหน้า 30 <b>"การเกิดฝ้าคลุมบาดแผล ( pseudoeschar) ที่เกิดขึ้นหลังจากใช้ยาไปได้ 2-3 วัน ทำให้บางครั้งแยกออกได้ยากจากบาดแผล( eschar)"</b>''',
 wrong={
 'A':'''การตกตะกอนของเงินจนเป็นสีน้ำตาลดำเป็นลักษณะของ silver nitrate ที่สัมผัสแสงและสารอินทรีย์ ไม่ใช่ฟิล์มสีเหลืองเทาของครีม SSD ซึ่งข้อดีข้อหนึ่งคือไม่เปื้อนสี · จะถูกถ้าหญิงที่แผลไหม้ได้ผ้าชุบ silver nitrate 0.5% มา 2 วัน แล้วแผล ผิวรอบแผล และผ้าปูที่นอนเป็นรอยสีน้ำตาลดำที่ล้างไม่ออก''',
 'B':'''Eschar จริงคือเนื้อตายจากความร้อน สีขาว น้ำตาล หรือดำ แข็งเหมือนหนัง ไม่รู้สึก มีตั้งแต่แรกบาดเจ็บก่อนทายา และติดแน่นกับพื้นแผลจนเช็ดไม่ออก · จะถูกถ้าชายที่ถูกท่อไอเสียรถจักรยานยนต์ลวกที่น่อง มาโรงพยาบาลในชั่วโมงแรก พบแผลแข็งสีขาวขุ่น ไม่เจ็บเมื่อใช้เข็มจิ้ม และยังไม่เคยทายาใด ๆ''',
 'C':'''เชื้อราลุกลามในแผลไหม้มักเกิดในแผลกว้างช่วงสัปดาห์ที่ 2–3 ขึ้นไป โดยเฉพาะหลังได้ยาปฏิชีวนะกว้าง แผลมีจุดดำหรือม่วงเทาลามเร็ว ขอบบวม และ eschar หลุดเร็วผิดปกติ ไม่ใช่ฟิล์มเรียบที่เกิดวันที่ 3 · จะถูกถ้าหญิงแผลไหม้ 50% วันที่ 16 ที่แผลมีปื้นดำลามขึ้นทุกวัน ไขมันใต้แผลบวมคล้ำ และชิ้นเนื้อพบสายราแทรกเข้าเนื้อเยื่อที่ยังดี''',
 'D':'''Graft ที่ติดดีเป็นแผ่นผิวสีชมพูที่ติดแน่นกับพื้นแผลหลังผ่าตัดราว 3–5 วัน กดซีดแล้วสีกลับเพราะเส้นเลือดเชื่อมต่อแล้ว ผู้ป่วยในโจทย์ไม่ได้รับการผ่าตัดปลูกผิว · จะถูกถ้าชายที่ได้ split-thickness graft บนแผลที่ตัดเนื้อตายแล้ว เปิดแผลครั้งแรกวันที่ 5 พบแผ่นผิวสีชมพูติดแน่นทั่วแผ่น ไม่มีเลือดคั่งหรือน้ำขังใต้แผ่น'''},
 trap='''ฟิล์มเหลืองเทาที่ติดแผลดูคล้ายเนื้อตายจนเลือก full-thickness eschar หรือคิดว่าติดเชื้อ — ตัวแยก: เกิดหลังเริ่ม SSD 2–3 วัน · เป็นชั้นผิวบนที่เช็ดออกได้ · ใต้ฟิล์มเป็นแผล partial thickness เดิม และไม่มีอาการติดเชื้อ''',
 summary=['''ฟิล์มเหลืองเทาคลุมแผลหลังใช้ SSD 2–3 วัน = pseudoeschar''',
  '''เกิดจากครีม SSD จับกับ exudate และโปรตีนจากแผล — ทำให้ประเมินความลึกผิดและแยกจาก eschar ได้ยาก''',
  '''ต่างจาก eschar จริง: เช็ดหรือล้างออกได้ · ใต้ฟิล์มยังเห็นพื้นแผลชมพูชื้น · eschar มีมาตั้งแต่บาดเจ็บและติดแน่น''',
  '''ป้องกัน: ล้างครีมเก่าออกหมดทุกครั้ง ทาชั้นบางสม่ำเสมอ''',
  '''ข้อเสียของ SSD บนสไลด์มีสองข้อ: Pseudoeschar · Leukopenia (WBC rarely &lt; 2000)''',
  '''รอยน้ำตาลดำ = silver nitrate · ปื้นดำลามเร็วสัปดาห์ที่ 2–3 = สงสัยเชื้อรา'''],
 opinion='''เห็นด้วยกับคำตอบ E ความมั่นใจสูง — สไลด์หน้า 66 ระบุ pseudoeschar เป็นข้อเสียแรกของ SSD และชีทหน้า 30 ให้ระยะเวลา 2–3 วันตรงกับโจทย์ · ข้อเสริมจากตำรา (Herndon's Total Burn Care 2018): pseudoeschar ทำให้การประเมินความลึกด้วยตาเชื่อถือได้น้อยลง ศูนย์ที่ประเมินแผลซ้ำวันที่ 3–5 เพื่อตัดสินใจผ่าตัดจึงต้องล้างครีมออกให้สะอาดก่อนตรวจ หรือเลือก dressing ชนิดอื่นในแผลที่ยังบอกความลึกไม่ได้''',
 mnemonic='''<b>"SSD 3 วัน ฝ้าเหลืองหลอกตา = Pseudo เช็ดออกได้"</b>''',
 guide='''Herndon's Total Burn Care 5th ed. (2018) — Burn wound care; ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021)''',
 variants=['''แพทย์ประเมินแผลที่ทา SSD วันที่ 4 แล้วคิดว่าเป็น full thickness ทั้งแผ่น แต่หลังล้างครีมออกพบพื้นชมพูชื้นกดซีด → เป็น partial thickness ที่ถูก pseudoeschar บัง ยังไม่ต้องผ่าตัด''',
  '''หญิงแผลไหม้ที่ญาติทาครีม SSD ซ้ำทับครีมเก่าทุกวันโดยไม่ล้าง → ฟิล์มหนาขึ้นเรื่อย ๆ จนแผลแฉะและประเมินไม่ได้ ต้องล้างครีมเก่าออกทุกครั้งก่อนทาใหม่''',
  '''ชายแผลไหม้ลึกที่ทา mafenide ติดต่อกันหลายสัปดาห์แล้วมีราขึ้นบนแผล → mafenide มีฤทธิ์ต้านราน้อย ต่างจาก SSD ที่ครอบคลุม Candida ด้วย จึงอาจสลับยาหรือเพิ่มยาต้านรา'''])

mk(Q, 107, [66, 67, 's30'],
 stem='''A deep ear burn has thick eschar and early chondritis. Which topical agent penetrates eschar and cartilage best?''',
 opts=['''1% silver sulfadiazine''','''Bacitracin ointment''','''Mafenide acetate''','''0.5% silver nitrate solution''','''Plain petroleum jelly'''],
 interp='''แผลไหม้ลึกที่ใบหูมี eschar หนาและกระดูกอ่อนเริ่มอักเสบ → ต้องการยาทาที่ลงไปถึงใต้ eschar และเข้ากระดูกอ่อนที่ไม่มีเส้นเลือดเลี้ยงของตัวเอง → ถามว่ายาทาตัวใดซึมได้ดีที่สุด ต้องเทียบความสามารถ penetration ของยาทาแต่ละตัว''',
 why='''กระดูกอ่อนใบหูและจมูก<b>ไม่มีเส้นเลือดของตัวเอง</b> อาศัยการซึมจาก perichondrium และผิวหนังบาง ๆ ที่คลุมอยู่ เมื่อผิวไหม้ลึกกระดูกอ่อนจึงเสี่ยง<b>ติดเชื้อ (suppurative chondritis)</b> โดยเฉพาะ <b>Pseudomonas</b> และยาทางหลอดเลือดเข้าถึงได้น้อย ถ้าลุกลามกระดูกอ่อนจะตายและหูยุบผิดรูปถาวร · <b>Mafenide acetate</b> เป็นยาทาที่<b>ซึมผ่าน eschar ได้ดีที่สุด</b>และ<b>ซึมเข้ากระดูกอ่อนได้</b> ครอบคลุมเชื้อกว้างรวม Pseudomonas ทาทุก 12 ชม. จึงเป็นยาที่เลือกสำหรับหูและจมูก — ต่างจาก SSD ที่ซึมได้ปานกลาง และ silver nitrate ที่ออกฤทธิ์เฉพาะผิวบน · ร่วมกับการดูแลอื่น: <b>เลี่ยงแรงกดที่หู</b> (ไม่หนุนหมอนด้านนั้น ใช้ห่วงรองศีรษะ) และถ้ามีหนองหรือกระดูกอ่อนตายต้องผ่าระบายและตัดกระดูกอ่อนส่วนที่ตายออก · ชีทหน้า 30 <b>"สามารถซึมผ่านกระดูกอ่อนได้ทำให้สารนี้เหมาะสำหรับการใช้ในบาดแผลไฟไหม้น้ำร้อนลวกบริเวณหูและจมูก"</b>''',
 wrong={
 'A':'''SSD ครอบคลุมเชื้อกว้างและปวดน้อย แต่การซึมผ่านแผลอยู่ในระดับปานกลาง (Penetration-Intermediate) ลงใต้ eschar หนาได้ไม่ดี และไม่ได้เด่นเรื่องการซึมเข้ากระดูกอ่อน · ไม่มีสถานการณ์ใดที่ SSD เป็นยาที่ซึมผ่าน eschar และกระดูกอ่อนได้ดีที่สุด เพราะการซึมปานกลางเป็นคุณสมบัติคงที่ของยา SSD จึงเหมาะกับแผลที่ต้องการความสบายมากกว่าการซึมลึก''',
 'B':'''Bacitracin ออกฤทธิ์ต่อแบคทีเรียแกรมบวกเป็นหลัก เป็นขี้ผึ้งที่ทำงานบนผิวแผลตื้น ใช้บ่อยกับแผลตื้นที่หน้าและแผลเล็ก ไม่ครอบคลุม Pseudomonas ซึ่งเป็นเชื้อสำคัญของ chondritis · ไม่มีสถานการณ์ใดที่ bacitracin ซึมผ่าน eschar หนาได้ดีที่สุด เพราะฐานขี้ผึ้งไม่ซึมลงเนื้อตาย และขอบเขตฤทธิ์แคบเกินกว่าจะคุมการติดเชื้อในกระดูกอ่อน''',
 'D':'''Silver nitrate 0.5% ครอบคลุมเชื้อกว้าง แต่ออกฤทธิ์เฉพาะผิวบน เพราะไอออนเงินจับกับโปรตีนและคลอไรด์บนผิวแผลจนตกตะกอนก่อนลงลึก จึงซึม eschar ได้น้อย · ไม่มีสถานการณ์ใดที่ silver nitrate ซึมผ่าน eschar หรือกระดูกอ่อนได้ดีที่สุด เพราะการตกตะกอนที่ผิวคือกลไกเดียวกับที่ทำให้แผลเปื้อนดำ ยานี้เด่นด้านไม่ปวดและใช้ได้ในผู้แพ้ sulfa''',
 'E':'''Petroleum jelly เป็นเพียงสารให้ความชุ่มชื้นและกันผ้าติดแผล ไม่มีฤทธิ์ฆ่าเชื้อ ใช้กับแผลที่หายแล้วหรือแผลตื้นที่สะอาด · ไม่มีสถานการณ์ใดที่ petroleum jelly ซึมผ่าน eschar หรือรักษากระดูกอ่อนอักเสบได้ เพราะไม่มีตัวยาต้านเชื้อ และชั้นน้ำมันเพียงเคลือบผิวด้านบน ในแผลติดเชื้อยังอาจปิดทับหนองไว้ด้วย'''},
 trap='''ยาทาทุกตัวในช้อยใช้กับแผลได้ และ SSD เป็นยาที่คุ้นที่สุดจึงถูกเลือกโดยอัตโนมัติ — แต่คำถามถามเรื่องการซึม: mafenide = Best Eschar Penetration + Cartilage Penetration ส่วน SSD ซึมได้แค่ปานกลาง''',
 summary=['''ซึม eschar ดีที่สุด + ซึมกระดูกอ่อน = mafenide acetate → ยาที่เลือกสำหรับแผลลึกที่หูและจมูก''',
  '''กระดูกอ่อนไม่มีเส้นเลือดของตัวเอง → ยาทางหลอดเลือดเข้าถึงน้อย ติดเชื้อง่าย โดยเฉพาะ Pseudomonas''',
  '''Suppurative chondritis ที่ปล่อยไว้ → กระดูกอ่อนตาย หูยุบผิดรูปถาวร''',
  '''ดูแลหูไหม้: เลี่ยงแรงกด ไม่หนุนหมอนด้านนั้น · ทา mafenide · มีหนองต้องผ่าระบายและตัดกระดูกอ่อนที่ตาย''',
  '''ลำดับการซึม: mafenide (ดีสุด) &gt; SSD (ปานกลาง) &gt; silver nitrate (ผิวบน)''',
  '''ราคาของ mafenide: ปวดมาก · acidosis เมื่อทาพื้นที่กว้าง จึงมักใช้เฉพาะจุด'''],
 opinion='''เห็นด้วยกับคำตอบ C ความมั่นใจสูง — สไลด์หน้า 67 ระบุ Best Eschar Penetration และ Catilage Penetration ส่วนชีทหน้า 30 ระบุชัดว่าเหมาะกับหูและจมูก · ตำราปัจจุบัน (Herndon's Total Burn Care 2018, Sabiston 2022) ยังใช้ mafenide กับแผลไหม้ลึกที่หูเป็นมาตรฐาน · ข้อสังเกต: คำบนสไลด์สะกด Catilage ซึ่งหมายถึง cartilage และสไลด์ไม่ได้พูดถึงการผ่าตัดเอากระดูกอ่อนที่ตายออกเมื่อเป็นหนอง ซึ่งยาทาอย่างเดียวรักษาไม่ได้''',
 mnemonic='''<b>"Mafenide = Most penetrating: ทะลุ eschar ถึงกระดูกอ่อน หู-จมูก"</b>''',
 guide='''Herndon's Total Burn Care 5th ed. (2018) — Burn wound care; Sabiston Textbook of Surgery 21st ed. (2022) — Burns''',
 variants=['''ชายแผลไหม้ใบหูที่ทา mafenide แต่ 1 สัปดาห์ต่อมาใบหูบวมแดงร้อน กดเจ็บ มีหนองใต้ผิว → suppurative chondritis ต้องผ่าระบาย ตัดกระดูกอ่อนที่ตายออก และให้ยาครอบคลุม Pseudomonas''',
  '''หญิงแผลไหม้ที่ใบหูนอนตะแคงทับหูข้างที่ไหม้ทั้งคืน → แรงกดลดเลือดไปเลี้ยงกระดูกอ่อนจนเสี่ยงตาย ใช้ห่วงรองศีรษะและห้ามหนุนหมอนด้านนั้น''',
  '''ชายหลังตัดเนื้อตายและวาง meshed autograft ต้องการน้ำยาชุบ dressing ฆ่าเชื้อคลุม graft → ใช้ mafenide ชนิดสารละลาย 5% ชุบ dressing บน graft ได้'''])

mk(Q, 108, [67, 's30'],
 stem='''A 40-year-old woman with 35% TBSA burns becomes tachypneic on day 4 of a topical agent. Her pH is 7.29, HCO3⁻ 16 mEq/L and Cl⁻ 116 mEq/L, with a normal anion gap and alkaline urine. Which agent is responsible?''',
 opts=['''Bacitracin ointment''','''Chlorhexidine gluconate wash''','''Silver sulfadiazine cream''','''Mafenide acetate''','''0.5% silver nitrate soaks'''],
 interp='''ผู้ป่วยแผลไหม้ 35% ใช้ยาทามา 4 วัน หายใจเร็ว blood gas เป็น metabolic acidosis ที่ Cl สูง anion gap ปกติ และปัสสาวะเป็นด่าง → hyperchloremic (normal AG) metabolic acidosis จากการเสีย HCO₃⁻ ทางไต → ถามว่ายาทาตัวใดเป็นต้นเหตุ ต้องรู้ว่ายาทาตัวใดยับยั้ง carbonic anhydrase''',
 why='''<b>Mafenide</b> เป็น <b>strong carbonic anhydrase inhibitor</b> ที่ดูดซึมจากแผลได้ ฤทธิ์ที่ท่อไตส่วนต้นทำให้<b>ดูดกลับ HCO₃⁻ ไม่ได้</b> → ปัสสาวะออกมากและเป็นด่าง (<b>alkaline diuresis</b>) → HCO₃⁻ ในเลือดลด ไตเก็บ Cl⁻ ไว้แทน → <b>hyperchloremic metabolic acidosis ที่ anion gap ปกติ</b> · ร่างกายชดเชยด้วย<b>การหายใจเร็วลึก (hyperventilation)</b> เพื่อลด PaCO₂ ผู้ที่มีโรคปอดเดิมหรือใช้เครื่องช่วยหายใจที่ตั้งค่าตายตัวชดเชยไม่ได้ จึงเกิด <b>pulmonary failure</b> · ความเสี่ยงสูงเมื่อทา<b>พื้นที่เกิน 20% TBSA</b> · การแก้คือหยุดหรือสลับเป็นยาทาอื่น ภาวะนี้กลับปกติใน <b>24–36 ชม.</b>หลังหยุดยา · ต้องแยกจาก acidosis ที่ anion gap สูงในผู้ป่วยไฟไหม้ เช่น lactic acidosis จาก resuscitation ไม่พอหรือ sepsis และพิษ cyanide · สไลด์หน้า 67 <b>"Carbonic Anhydrase Inhibitor (- Hyperchloremic Metabolic Acidosis · - Pulmonary failure)"</b>''',
 wrong={
 'A':'''Bacitracin เป็นขี้ผึ้งฆ่าเชื้อแกรมบวกที่ดูดซึมผ่านผิวน้อยมาก ผลข้างเคียงหลักคือผื่นแพ้สัมผัส ไม่มีผลต่อการขับกรดด่างของไต · ไม่มีสถานการณ์ใดที่ bacitracin ทาผิวเป็นต้นเหตุของ hyperchloremic metabolic acidosis เพราะยาไม่ได้ยับยั้ง carbonic anhydrase และใช้กับแผลตื้นพื้นที่เล็กเป็นหลัก''',
 'B':'''Chlorhexidine ใช้ล้างทำความสะอาดแผลและผิว ผลข้างเคียงคือระคายเคือง แพ้ และเป็นพิษต่อตาและหูชั้นกลางถ้าเข้าไป ไม่ได้ถูกดูดซึมจนเปลี่ยนสมดุลกรดด่าง · ไม่มีสถานการณ์ใดที่ chlorhexidine เป็นต้นเหตุของ acidosis ชนิด Cl สูง AG ปกติ เพราะไม่มีฤทธิ์ต่อการดูดกลับ HCO₃⁻ ที่ไต acidosis ระหว่างล้างแผลกว้างจึงต้องหาสาเหตุจากระบบอื่น''',
 'C':'''SSD ดูดซึมเข้าสู่ร่างกายน้อยมาก (Rare Systemic Absorption) ผลต่อเลือดที่สำคัญคือ WBC ลดชั่วคราวและ hemolysis ในผู้ที่ขาด G6PD ไม่ใช่ความผิดปกติกรดด่าง · ไม่มีสถานการณ์ใดที่ SSD ทำให้ hyperchloremic metabolic acidosis เพราะไม่มีฤทธิ์ยับยั้ง carbonic anhydrase ยาทาที่มีฤทธิ์นี้คือ mafenide ซึ่งเป็นตัวที่สไลด์ระบุไว้''',
 'E':'''Silver nitrate 0.5% เป็นน้ำยา hypotonic ที่ดึง Na, K, Cl และ Ca ออกทางแผล จึงทำให้ Na และ Cl ในเลือดต่ำ ไม่ใช่ Cl สูง และอาจเกิด methemoglobinemia · ไม่มีสถานการณ์ใดที่ silver nitrate ทำให้ภาพเลือด Cl สูงแบบนี้ เพราะทิศทางของเกลือแร่ตรงข้ามกัน ยานี้ทำให้ hypochloremia ร่วมกับ hyponatremia'''},
 trap='''Acidosis ในผู้ป่วยไฟไหม้มักทำให้นึกถึง lactic acidosis จากช็อกหรือ sepsis จนไม่คิดถึงยาทา — ตัวแยกคือ anion gap: AG ปกติ + Cl สูง + ปัสสาวะเป็นด่าง = เสีย HCO₃⁻ ทางไต = carbonic anhydrase inhibitor = mafenide''',
 summary=['''Hyperchloremic metabolic acidosis (AG ปกติ) + หายใจเร็ว ในผู้ใช้ยาทา = mafenide''',
  '''กลไก: ยับยั้ง carbonic anhydrase ที่ท่อไต → เสีย HCO₃⁻ ทางปัสสาวะ (alkaline diuresis) → Cl ขึ้นแทน''',
  '''ชดเชยด้วย hyperventilation — ผู้ป่วยโรคปอดหรือใช้เครื่องช่วยหายใจตั้งค่าตายตัวเสี่ยง pulmonary failure''',
  '''เสี่ยงเมื่อทาเกิน 20% TBSA (ชีทหน้า 30)''',
  '''หยุดหรือสลับยา → กลับปกติใน 24–36 ชม.''',
  '''Acidosis ที่ AG สูงในผู้ป่วยไฟไหม้ → คิดถึง lactic acidosis จาก hypoperfusion, sepsis และ cyanide'''],
 opinion='''เห็นด้วยกับคำตอบ D ความมั่นใจสูง — สไลด์หน้า 67 และชีทหน้า 30 บรรยายกลไกและอาการตรงกับโจทย์ ทั้ง carbonic anhydrase inhibition, hyperchloremic metabolic acidosis และการหายใจเร็ว · ข้อเสริม: ตำราปัจจุบัน (Herndon's Total Burn Care 2018) แนะนำให้จำกัด mafenide เฉพาะพื้นที่ที่ต้องการการซึมลึก หรือใช้สลับกับ SSD เพื่อลดทั้งความปวดและ acidosis และควรตรวจ electrolytes กับ blood gas เป็นระยะเมื่อทาพื้นที่กว้าง''',
 mnemonic='''<b>"Mafenide ทำตัวเหมือน acetazolamide ที่แผล: AG ปกติ Cl สูง หายใจหอบ"</b>''',
 guide='''Herndon's Total Burn Care 5th ed. (2018) — Burn wound care; Sabiston Textbook of Surgery 21st ed. (2022) — Burns''',
 variants=['''ชายโรคปอดอุดกั้นเรื้อรังใส่เครื่องช่วยหายใจแบบตั้งอัตราหายใจคงที่ ทา mafenide พื้นที่ 30% → ชดเชยด้วยการหายใจเร็วไม่ได้ pH ลดลงเรื่อย ๆ ต้องหยุด mafenide และปรับเครื่อง''',
  '''หญิงแผลไหม้ 40% ที่ใช้ mafenide มี pH 7.25 แต่ anion gap 22 และ lactate 6 mmol/L → acidosis นี้ไม่ได้มาจาก mafenide ต้องหา hypoperfusion หรือ sepsis''',
  '''ชายใช้ mafenide เฉพาะที่หูและจมูกรวมราว 2% TBSA → ความเสี่ยง acidosis ต่ำมากเพราะดูดซึมน้อยเมื่อทาพื้นที่เล็ก ใช้ต่อได้โดยเฝ้าดูอาการ'''])

mk(Q, 109, [66, 67, 's30'],
 stem='''A 30-year-old man has severe burning pain each time his topical burn agent is applied. Which agent is most likely?''',
 opts=['''Paraffin gauze dressing''','''Mafenide acetate''','''Silver sulfadiazine cream''','''Hydrocolloid dressing''','''0.5% silver nitrate solution'''],
 interp='''ผู้ป่วยแสบปวดมากทุกครั้งที่ทายาทาแผลไหม้ → ถามว่ายาทาตัวใดมีผลข้างเคียงเด่นคือปวด ต้องรู้ข้อเสียประจำตัวของยาทาแต่ละตัว และแยกยาฆ่าเชื้อออกจากวัสดุปิดแผลที่ไม่มีตัวยา''',
 why='''<b>Mafenide acetate</b> (ครีม 11.1%) มีข้อเสียข้อแรกบนสไลด์คือ <b>Significantly Painful</b> — ผู้ป่วยมักแสบร้อนมากหลังทาและเป็นอยู่หลายนาที ซึ่งเป็นปัญหามากเมื่อต้องทาวันละ 2 ครั้ง (ทุก 12 ชม.) ในผู้ป่วยที่รู้ตัวดีและในเด็ก · ยานี้ยังถูกเลือกใช้เพราะ<b>ซึมผ่าน eschar ได้ดีที่สุดและซึมเข้ากระดูกอ่อน</b> ครอบคลุม Pseudomonas ได้ดี · วิธีลดปัญหาปวด: ให้<b>ยาแก้ปวดก่อนทา</b> ใช้เฉพาะบริเวณที่จำเป็นต้องการการซึมลึก หรือ<b>สลับกับ SSD</b> (เช่น mafenide ช่วงหนึ่งของวัน SSD อีกช่วงหนึ่ง) ซึ่งช่วยลดความเสี่ยง acidosis ไปพร้อมกัน · ตรงข้ามกับ SSD ที่ข้อดีคือ <b>Minimal Pain</b> และ silver nitrate ที่ไม่ปวดแต่เปื้อนดำ ส่วนวัสดุปิดแผลอย่าง paraffin gauze และ hydrocolloid ไม่มีตัวยาที่ระคายแผล · สไลด์หน้า 67 <b>"Disadvantages: Significantly Painful"</b>''',
 wrong={
 'A':'''ผ้าก๊อซชุบพาราฟิน (paraffin gauze) เป็นวัสดุปิดแผลชั้นในที่ไม่ติดแผล ไม่มีตัวยาฆ่าเชื้อ มีไว้ลดความเจ็บและการฉีกผิวใหม่ตอนเปลี่ยนผ้า · ไม่มีสถานการณ์ใดที่ paraffin gauze เป็นต้นเหตุของอาการแสบมากทุกครั้งที่วาง เพราะไม่มีสารออกฤทธิ์ที่ระคายแผล ความเจ็บที่เกี่ยวข้องมักเกิดเมื่อผ้าชั้นนอกแห้งติดแผลแล้วถูกดึงออก ไม่ใช่ตอนวาง''',
 'C':'''SSD เป็นครีมฐานน้ำที่ทาแล้วรู้สึกเย็นสบาย ข้อดีบนสไลด์คือ Minimal Pain จึงเป็นยาทาที่ใช้มากที่สุด ข้อเสียคือ pseudoeschar และ leukopenia · ไม่มีสถานการณ์ใดที่ SSD เป็นยาทาที่เด่นเรื่องปวดแสบ เพราะความปวดน้อยเป็นคุณสมบัติประจำตัวของยา ถ้าผู้ป่วยแสบมากหลังทา SSD ให้คิดถึงการแพ้ยาหรือแผลติดเชื้อมากกว่าฤทธิ์ปกติของยา''',
 'D':'''Hydrocolloid เป็นแผ่นปิดแผลแบบชุ่มชื้นที่ไม่มียาฆ่าเชื้อ ใช้กับแผลตื้นเล็กที่สะอาด ช่วยลดปวดเพราะคลุมปลายประสาทให้ชุ่มชื้นและไม่ต้องเปลี่ยนบ่อย · ไม่มีสถานการณ์ใดที่ hydrocolloid ทำให้แสบมากทุกครั้งที่วาง เพราะไม่มีสารระคายเคือง ปัญหาของแผ่นนี้คือสิ่งคัดหลั่งสะสมจนแผ่นหลุด หรือมีของเหลวกลิ่นคล้ายหนองที่ไม่ใช่การติดเชื้อ''',
 'E':'''Silver nitrate 0.5% เป็นน้ำยาเจือจางที่ชุบผ้าคลุมแผล ใช้แล้วไม่ปวด ปัญหาหลักคือดึงเกลือแร่ออก methemoglobinemia เปื้อนดำ และต้องชุบให้เปียกทุก 2 ชม. · ไม่มีสถานการณ์ใดที่ silver nitrate เป็นยาที่เด่นเรื่องปวดแสบ เพราะความเข้มข้น 0.5% ถูกเลือกให้ฆ่าเชื้อได้โดยไม่ทำลายเซลล์และไม่ระคายปลายประสาท ความไม่ปวดจึงเป็นข้อดีประจำตัวของยา'''},
 trap='''ยาฆ่าเชื้อทุกตัวดูน่าจะแสบ จึงเลือกตัวที่คุ้นที่สุดอย่าง SSD — แต่ SSD ขึ้นชื่อว่า Minimal Pain · ยาทาที่ข้อเสียเด่นคือปวดมีตัวเดียวคือ mafenide ส่วนวัสดุปิดแผลที่ไม่มีตัวยาไม่ทำให้แสบ''',
 summary=['''แสบปวดมากทุกครั้งที่ทา = mafenide acetate (Significantly Painful)''',
  '''ทาทุก 12 ชม. → ปวดซ้ำวันละ 2 ครั้ง เป็นปัญหามากในเด็กและผู้ป่วยที่รู้ตัวดี''',
  '''ลดปวด: ยาแก้ปวดก่อนทา · ใช้เฉพาะบริเวณที่ต้องการการซึมลึก · สลับกับ SSD''',
  '''ยังเลือกใช้เพราะ: ซึม eschar ดีที่สุด + ซึมกระดูกอ่อน + ครอบคลุม Pseudomonas''',
  '''ไม่ปวด: SSD (Minimal Pain) · silver nitrate · วัสดุที่ไม่มีตัวยา เช่น paraffin gauze, hydrocolloid''',
  '''ข้อเสียอีกข้อของ mafenide: carbonic anhydrase inhibitor → hyperchloremic metabolic acidosis'''],
 opinion='''เห็นด้วยกับคำตอบ B ความมั่นใจสูง — สไลด์หน้า 67 ระบุ Significantly Painful และชีทหน้า 30 เขียนว่าการใช้สารนี้มักทำให้มีอาการปวดมาก ขณะที่สไลด์หน้า 66 ให้ SSD เป็น Minimal Pain · ข้อเสริม: ในทางปฏิบัติปัจจุบันการทำแผลไหม้ทุกชนิดเจ็บ ISBI Practice Guidelines 2016 จึงให้วางแผนระงับปวดก่อนทำแผลทุกครั้ง (procedural analgesia) ไม่ว่าใช้ยาทาตัวใด แต่ mafenide เพิ่มความแสบจากตัวยาเองหลังทา''',
 mnemonic='''<b>"Mafenide = Mega pain · SSD = Soothing"</b>''',
 guide='''ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021) — Pain management and wound care; Herndon's Total Burn Care 5th ed. (2018) — Burn wound care''',
 variants=['''เด็กอายุ 6 ปีแผลไหม้ลึกที่แขนซึ่งมีหนองใต้ eschar ร้องดิ้นทุกครั้งที่ทา mafenide → ให้ยาแก้ปวดและยาคลายกังวลก่อนทำแผลทุกรอบ และจำกัดการทาเฉพาะบริเวณที่จำเป็น''',
  '''ชายแผลไหม้ลึก 30% ทา mafenide ทั้งวันแล้วปวดมากและ HCO₃⁻ เริ่มลด → สลับเป็น mafenide ช่วงกลางวันและ SSD ช่วงกลางคืน ลดทั้งความปวดและ acidosis''',
  '''หญิงแผล partial thickness ปวดมากทุกครั้งที่ดึงผ้าก๊อซแห้งออก → ใช้ผ้าชั้นในที่ไม่ติดแผล เช่น paraffin gauze หรือ silicone mesh และชุบน้ำเกลือก่อนแกะ'''])

mk(Q, 110, [65, 66, 67, 's30'],
 stem='''Two days into 0.5% silver nitrate soaks, a 28-year-old woman with burns has a sodium of 126 mEq/L and black-stained sheets. Which statement is correct?''',
 opts=['''The hyponatremia indicates burn wound sepsis''','''Silver nitrate commonly causes leukopenia''','''The hypotonic soak leaches electrolytes through the wound''','''Silver nitrate penetrates eschar better than mafenide does''','''Silver nitrate inhibits carbonic anhydrase and causes acidosis'''],
 interp='''ผู้ป่วยแผลไหม้ใช้ผ้าชุบ silver nitrate 0.5% สองวัน Na ลดเหลือ 126 และผ้าปูที่นอนเปื้อนดำ → ภาพเข้ากับผลข้างเคียงของ silver nitrate → ถามข้อความที่ถูก ต้องรู้ว่าน้ำยาเป็น hypotonic ที่ดึงเกลือแร่ออกทางแผล และแยกจากข้อเสียของ SSD กับ mafenide''',
 why='''<b>Silver nitrate 0.5%</b> ใช้ความเข้มข้นที่ฆ่าเชื้อได้กว้างแต่ไม่ทำลายเซลล์ และดูดซึมเข้าร่างกายน้อย ปัญหาคือเป็น<b>สารละลาย hypotonic</b> ที่แทบไม่มี Na คลุมแผลเปิดพื้นที่กว้างตลอดเวลา เกลือแร่จึง<b>ซึมออกจากร่างกายผ่านแผลลงสู่ผ้าชุบ</b> → <b>Na, K, Cl และ Ca ต่ำ</b> โดยเฉพาะในเด็กและแผลกว้าง ต้องตรวจเกลือแร่บ่อยและเสริมเกลือ · ข้อเสียอื่น: <b>methemoglobinemia</b> เมื่อแบคทีเรียบางชนิดเปลี่ยน nitrate เป็น nitrite · <b>ซึม eschar ได้น้อย</b> ออกฤทธิ์ที่ผิวบน · ต้อง<b>ชุบให้เปียกทุก 2 ชม.</b> ไม่ให้ระเหยจนเข้มข้นเกิน 2% ซึ่งเป็นพิษต่อเซลล์ · <b>เปื้อนสีน้ำตาลดำ</b>ทุกสิ่งที่สัมผัส · ข้อดีคือไม่ปวดและไม่มี sulfa จึงใช้ในผู้แพ้ sulfa ได้ · ชีทหน้า 30 <b>"สารนี้ทำให้เกิดความผิดปกติของระดับเกลือแร่ในเลือด( serum electrolytes) เนื่องจากคุณสมบัติของสารนี้ที่เป็นสารละลายเจือจาง( hypotonic solution)"</b>''',
 wrong={
 'A':'''Na ต่ำในผู้ป่วยไฟไหม้มีหลายสาเหตุ sepsis เป็นหนึ่งในนั้น แต่ผู้ป่วยในโจทย์ไม่มีสัญญาณติดเชื้อ และมีต้นเหตุที่อธิบายได้ตรงกว่าคือน้ำยา hypotonic คลุมแผล · จะถูกถ้าชายแผลไหม้ 45% ที่ทา SSD วันที่ 10 มี Na 128 ร่วมกับไข้ 39.8°C หัวใจเร็ว เกล็ดเลือดลด ลำไส้ไม่ทำงาน และแผลเปลี่ยนสี โดยไม่ได้ใช้ silver nitrate''',
 'B':'''Leukopenia ชั่วคราวเป็นข้อเสียประจำตัวของ SSD เกิดวันที่ 2–3 และมักไม่ต่ำกว่า 2,000 ไม่ใช่ของ silver nitrate ซึ่งพิษต่อเลือดที่สำคัญคือ methemoglobinemia · ไม่มีสถานการณ์ใดที่ silver nitrate เป็นสาเหตุที่พบบ่อยของ leukopenia เพราะยาตกตะกอนและออกฤทธิ์ที่ผิวแผล ดูดซึมเข้าร่างกายน้อย และไม่มีส่วนประกอบ sulfonamide''',
 'D':'''Mafenide ซึม eschar ได้ดีที่สุดในกลุ่มยาทา ส่วน silver nitrate ซึมได้น้อยเพราะไอออนเงินจับกับคลอไรด์และโปรตีนที่ผิวแผลจนตกตะกอน · ไม่มีสถานการณ์ใดที่ silver nitrate ซึม eschar ได้ดีกว่า mafenide เพราะลำดับการซึมเป็นคุณสมบัติคงที่ของยา: mafenide ดีที่สุด SSD ปานกลาง และ silver nitrate ออกฤทธิ์เฉพาะผิวบน''',
 'E':'''การยับยั้ง carbonic anhydrase จนเกิด hyperchloremic metabolic acidosis เป็นกลไกของ mafenide ส่วน silver nitrate กลับทำให้ Cl ต่ำ ซึ่งทิศทางตรงข้ามกับ acidosis ชนิด Cl สูง · ไม่มีสถานการณ์ใดที่ silver nitrate ยับยั้ง carbonic anhydrase เพราะยาไม่มีโครงสร้าง sulfonamide ที่จับเอนไซม์นี้ ปัญหาที่ยานี้ทำคือการเสียเกลือแร่ทางแผล ไม่ใช่การเสีย HCO₃⁻ ทางไต'''},
 trap='''Na ต่ำในผู้ป่วยไฟไหม้ชวนให้คิดว่าเป็น sepsis หรือให้น้ำมากเกิน และยาทาทั้งสามตัวมีข้อเสียทางเลือดที่จำสลับกันง่าย — จับคู่ให้แม่น: SSD = WBC ต่ำ · mafenide = acidosis Cl สูง · silver nitrate = เกลือแร่ต่ำ + MetHb + เปื้อนดำ''',
 summary=['''Silver nitrate 0.5% = น้ำยา hypotonic → ดึง Na, K, Cl, Ca ออกทางแผล + เปื้อนน้ำตาลดำ''',
  '''ต้องตรวจ electrolytes บ่อยและเสริมเกลือ โดยเฉพาะเด็กและแผลกว้าง''',
  '''Methemoglobinemia: แบคทีเรียบางชนิดเปลี่ยน nitrate → nitrite — เขียวคล้ำ SpO2 ต่ำทั้งที่ PaO2 ปกติ''',
  '''ชุบให้เปียกทุก 2 ชม. คงความเข้มข้นไม่ให้เกิน 2% ซึ่งเป็นพิษต่อเซลล์''',
  '''ซึม eschar ได้น้อย · ไม่ปวด · ดูดซึมน้อย · ไม่มี sulfa → ใช้ในผู้แพ้ sulfa ได้''',
  '''จับคู่ข้อเสีย: SSD = WBC ต่ำ · mafenide = acidosis Cl สูง + ปวด · silver nitrate = เกลือแร่ต่ำ'''],
 opinion='''เห็นด้วยกับคำตอบ C ความมั่นใจสูง — ชีทหน้า 30 อธิบายตรงทั้งกลไก hypotonic และการเปื้อนดำ ส่วนสไลด์หน้า 65 ระบุ silver nitrate (0.5% solution) เป็นหนึ่งในยาทาหลัก · ชีทเองระบุว่ายานี้ไม่เป็นที่นิยมแล้ว ซึ่งตรงกับปัจจุบัน: ศูนย์ส่วนใหญ่ใช้ dressing ที่ปลดปล่อยไอออนเงินแบบควบคุม (nanocrystalline silver) แทน เพราะได้ฤทธิ์ของเงินโดยไม่ต้องชุบทุก 2 ชม. และไม่ทำให้เกลือแร่ผิดปกติ (Herndon's Total Burn Care 2018)''',
 mnemonic='''<b>"Nitrate = Na ต่ำ + Night-black + MetHb"</b>''',
 guide='''Herndon's Total Burn Care 5th ed. (2018) — Burn wound care; Sabiston Textbook of Surgery 21st ed. (2022) — Burns''',
 variants=['''ชายใช้ผ้าชุบ silver nitrate วันที่ 3 ตัวเขียวคล้ำ เลือดสีน้ำตาลช็อกโกแลต SpO2 ราว 85% ทั้งที่ PaO2 ปกติ → methemoglobinemia ยืนยันด้วย co-oximetry และให้ methylene blue ถ้าไม่ขาด G6PD''',
  '''เด็กอายุ 3 ปีแผลไหม้ 30% ใช้ silver nitrate แล้วชัก Na 120 → hyponatremia จากเกลือแร่ซึมออกทางแผล แก้ Na อย่างระมัดระวังและเปลี่ยนยาทา''',
  '''พยาบาลปล่อยผ้าชุบ silver nitrate แห้งข้ามคืน → น้ำระเหยจนความเข้มข้นเกิน 2% เป็นพิษต่อเซลล์ที่งอกใหม่ ต้องชุบให้เปียกทุก 2 ชม.'''])

save(Q, 'parts/fill/l23_r11.json')
